(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.018-t*0.28)*18 + Math.sin(x*0.016+t*0.32)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const w2x = Math.sin(x*0.025-t*0.4)*6 + Math.cos(y*0.03+t*0.5)*5;
  const w2y = Math.cos(y*0.025+t*0.45)*6 + Math.sin(x*0.028-t*0.35)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.95],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.05],
    [60+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.75)*50, 0.11, 2.1, 0.8],
    [420+Math.cos(t*0.45+2)*60, 220+Math.sin(t*0.85+1)*40, 0.13, 1.8, 0.88],
    [200+Math.sin(t*0.55+4)*110, 30+Math.cos(t*0.65+3)*60, 0.075, 2.4, 1.0],
    [300+Math.cos(t*0.7+1)*90, 210+Math.sin(t*0.5+2)*70, 0.095, 2.0, 0.92]
  ];
  let aS=0, iS=0, cross=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp,w]=src[i];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
