    aS+=a*w; iS+=inh*w;
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2,f2,sp2]=src[j];
      const d2=Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
      cross+=Math.sin(d*f-t*sp)*Math.sin(d2*f2-t*sp2)*0.15;
    }
  }
  const act=aS/8.2, inh=iS/8.2;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.07*sy*0.0001+t*0.6)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
