  const voronoi=()=>{
    let mn=999,md=0;
    for(const[sX,sY]of src){
      const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
      if(d<mn){md=mn;mn=d;}else if(d<md){md=d;}
    }
    return Math.sin(mn*0.2-t)*Math.sin((md-mn)*0.3)*0.5;
  };
  const cell=voronoi();
  const feed=Math.tanh(act*1.8)*0.6-inh*0.3+cross*0.4;
  const kill=Math.tanh(inh*1.5)*0.5-act*0.2+bg*0.25;
  const reaction=Math.tanh((feed-kill+spiral+cell)*2.0);
  const fineDetail=Math.sin(sx*0.3+sy*0.25+t*3)*Math.sin(sx*0.2-sy*0.35-t*2.5)*0.15*(Math.abs(reaction)>0.5?1:0);
  const glow=Math.exp(-dist*0.008)*Math.sin(t*0.8)*0.15;
  const edge=1.0-Math.exp(-Math.abs(reaction)*8)*0.3;
  const blend=reaction*0.6+cell*0.15+fineDetail+glow, v=blend*0.5+0.5;
