    [5,12,45],[12,45,85],[18,90,120],[25,140,135],
    [45,175,145],[120,195,120],[195,190,80],
    [220,160,65],[210,115,60],[185,70,65],
    [140,40,70],[85,22,60],[35,15,50],[5,12,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+glow*0.5;
