  const g=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  return [
    Math.min(255,Math.max(0,(r+hueShift*60)*lum*edge))|0,
    Math.min(255,Math.max(0,(g+hueShift*30)*lum*edge))|0,
    Math.min(255,Math.max(0,(b-hueShift*40)*lum*edge))|0
  ];
}
